import sys
import heapq
from collections import defaultdict

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        print(-1)
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    graph = defaultdict(list)

    for _ in range(m):
        u = int(next(it))
        v = int(next(it))
        w = int(next(it))
        graph[u].append((v, w))

    k = int(next(it))

    dist = {i: float('inf') for i in range(1, n + 1)}
    dist[k] = 0

    heap = [(0, k)]

    while heap:
        d, u = heapq.heappop(heap)
        if d > dist[u]:
            continue
        for v, w in graph[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                heapq.heappush(heap, (dist[v], v))

    max_time = max(dist.values())

    if max_time == float('inf'):
        print(-1)
    else:
        print(max_time)

if __name__ == "__main__":
    main()
